fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    let l = n - (n % 3); // largest multiple of 3 <= n
    let mut out = Vec::with_capacity(n);

    // Process complete blocks of 3: [a, b, c] -> [b, c, a]
    let mut i = 0;
    while i < l {
        out.push(s[i + 1]);
        out.push(s[i + 2]);
        out.push(s[i]);
        i += 3;
    }

    // Copy any remaining 1 or 2 elements unchanged
    out.extend_from_slice(&s[l..]);

    out
}

